.header-meta-language #lang_sel { display: none; top: 55px; margin-left: -150px; }
.header-meta-language #lang_sel.lang-open { display: block; }
.header-meta-language #lang_sel:after { content: ""; height: 16px; width: 16px; position: absolute; background-color: #fff; top: -9px; left: 75%; border-top: 1px solid #fbf6f6; border-left: 1px solid #fbf6f6; transform: rotate(45deg); }

#mega-menu-wrap-avia #mega-menu-avia li.mega-menu-megamenu li.mega-menu-item.mega-icon-left.mega-has-description.mega-has-icon > a.mega-menu-link:before {border: none !important;}	
