/* Footer Space Removed */
@media only screen and (max-width: 489px) {#footer{padding: 15px 0 30px 0 !important;}}
/* Scroll to up */
#scroll-top-link, #av-cookie-consent-badge {display: flex !important;justify-content: center !important;align-items: center !important;}
#scroll-top-link.avia-svg-icon svg:first-child {margin-top: 0 !important;}

.av_minimal_header #header_main .container, .av_minimal_header .main_menu ul:first-child>li a, .header-right-group {height: 60px; top:0;} 
@media only screen and (max-width: 767px) {
	.responsive #top .av-logo-container .logo {height: 60px !important; width: 125px;}
}

#top #wrap_all #main .avia-section.pt-0 {padding-top: 0 !important;}
#top #main .flex_column.av_one_full .av-special-heading.w-800 {max-width: 800px; width: 100%;}
#top .career-why-skit .lsq-compliance-grid__icon-wrap {width: 60px; height: 60px;}

#top #main h1.av-special-heading-tag { font-size: 56px !important;text-transform: none;}
#top #main h2.av-special-heading-tag {font-size: 46px; text-transform: none;}
#top #main .lead p { font-size: 18px !important; max-width: 740px !important; color: #0b122099 !important; opacity: 1; margin: 0 auto 20px;}
.eyebrow, .eyebrowHead p {text-transform: uppercase;letter-spacing: 0.24em;font-size: .72rem !important;font-weight: 700 !important;color: #000000 !important;display: inline-block;margin-bottom: 14px !important;}

.career-est {display: flex; background: #fff; padding: 40px 50px; border-radius: 30px; justify-content: space-between; align-items: center;}
.career-est .flex-left {margin: 0 !important;}
#top #main .career-est .title .av-subheading.av-subheading_below p {margin: 0 !important;}

.offices-section {max-width: 720px; margin: 0 auto;}
.offices-heading {font-size: 13px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase; color: #0d1b2a; margin-bottom: 24px;}
.offices-grid {display: flex; gap: 20px;}
.office-card {flex: 1; background: #f2f6fb; border-radius: 20px; padding: 36px 20px 28px; text-align: center; display: flex; flex-direction: column; align-items: center; gap: 18px; min-width: 150px; background: #0f6fff;}
.office-card svg {width: 26px; height: 26px;}
.office-name {font-size: 16px; font-weight: 500; color: #fff;}
.office-icon {display: block; object-fit: contain; width: 60px; height: 60px;}

@media only screen and (max-width: 767px) {
	.career-est {flex-direction: column; gap: 30px; align-items: flex-start; margin-top: 30px !important; padding: 20px 30px;}
	.offices-grid {flex-direction: column;}
	.career-est section.avia_codeblock_section {width: 100%;}
}
@media only screen and (max-width: 600px) {
	#top #main h1.av-special-heading-tag  { font-size: 36px !important; line-height: 1.2 !important;}
	#top #main h2.av-special-heading-tag  { font-size: 36px !important; line-height: 1.2 !important;}
	#top #main .lead p { font-size: 16px !important; }
}

